// ─────────────────────────────────────────────────────────────
// Normaliza la entrada y arma rutas temporales únicas por ejecución.
// Cambiá los valores por defecto (cuenta, URL, voz) a tu instalación.
// ─────────────────────────────────────────────────────────────

// Algunas instalaciones bloquean $env en los Code nodes
// (N8N_BLOCK_ENV_ACCESS_IN_NODE=true), así que lo leemos sin romper.
const env = (clave) => {
  try { return $env[clave] || ''; } catch (e) { return ''; }
};

const CHATWOOT_URL    = (env('CHATWOOT_URL') || 'https://crmesteban.duckdns.org').replace(/\/$/, '');
const CHATWOOT_CUENTA = env('CHATWOOT_ACCOUNT_ID') || '1';
const VOZ_POR_DEFECTO = env('FISH_REFERENCE_ID');

return $input.all().map((item, i) => {
  const d = item.json || {};

  const texto = String(d.texto ?? d.text ?? d.output ?? d.message ?? '').trim();
  if (!texto) {
    throw new Error('No llegó texto para convertir en nota de voz (campo "texto").');
  }

  const conversationId = d.conversation_id ?? d.chatwoot_conversation_id ?? d.conversacion_id;
  if (!conversationId) {
    throw new Error('Falta conversation_id (el id de la conversación en Chatwoot).');
  }

  // Base única: evita que dos ejecuciones simultáneas pisen el mismo archivo.
  const base = `/tmp/tm_voz_${$execution.id}_${i}_${Date.now()}`;

  return {
    json: {
      texto,
      conversation_id: String(conversationId),
      reference_id: d.reference_id || VOZ_POR_DEFECTO,
      chatwoot_url: d.chatwoot_url || CHATWOOT_URL,
      account_id: d.account_id || CHATWOOT_CUENTA,
      // La nota de voz no lleva texto visible: WhatsApp muestra solo el audio.
      caption: d.caption ?? '',
      archivo_entrada: `${base}.in`,
      archivo_ogg: `${base}.ogg`,
      nombre_archivo: 'nota_de_voz.ogg'
    }
  };
});

