// ─────────────────────────────────────────────────────────────
// PASO CLAVE DEL ARREGLO.
// Meta rechaza el audio (error 131053) si el MIME es "audio/opus"
// o si el archivo se llama .opus / .webm / .mp3.
// Acá forzamos nombre .ogg + MIME "audio/ogg" y verificamos que el
// binario sea realmente un OGG con cabecera OpusHead.
// ─────────────────────────────────────────────────────────────
const prep = $('Preparar variables').item.json;
const bin = $input.item.binary && $input.item.binary.data;

if (!bin) throw new Error('No se recibió el archivo OGG desde el disco.');

// La firma del helper cambia según la versión de n8n y el modo de
// almacenamiento binario (memoria vs filesystem). Probamos las variantes.
let buffer;
try {
  buffer = await this.helpers.getBinaryDataBuffer('data');
} catch (e) {
  try {
    buffer = await this.helpers.getBinaryDataBuffer(0, 'data');
  } catch (e2) {
    buffer = Buffer.from(bin.data, 'base64');
  }
}

if (!buffer || buffer.length < 57) {
  throw new Error(`El OGG generado está vacío o es demasiado corto (${buffer ? buffer.length : 0} bytes).`);
}

// Firma del contenedor OGG: los 4 primeros bytes deben ser "OggS".
if (buffer.toString('latin1', 0, 4) !== 'OggS') {
  throw new Error('El archivo no es un contenedor OGG válido (falta la firma OggS).');
}

// La primera página debe contener la cabecera de identificación "OpusHead".
if (buffer.toString('latin1', 28, 36) !== 'OpusHead') {
  throw new Error('El OGG no contiene un stream Opus (falta OpusHead). Revisá que ffmpeg tenga libopus.');
}

const canales = buffer[37];

// Reescribimos los metadatos del binario: esto es lo que Chatwoot lee
// para decidir qué MIME manda a Meta.
bin.fileName = prep.nombre_archivo;   // nota_de_voz.ogg
bin.fileExtension = 'ogg';
bin.fileType = 'audio';
bin.mimeType = 'audio/ogg';           // NUNCA "audio/opus"

$input.item.json = {
  ...prep,
  ogg_bytes: buffer.length,
  ogg_canales: canales,
  ogg_valido: true
};

return $input.item;
